import type { LoaderAdapter, PlatformInput } from "./adapter"
import { CLIENT_PLATFORM_CLASS, PLATFORM_CLASS, PLATFORM_PACKAGE, addMixinClasses, platformPaths } from "./facade"

/**
 * Fabric 1.21.1. Its mods are still generated by the Fabric generator's own text (`fabric/*.ts`, `content.ts`), byte
 * for byte as before: `facade` is false, so nothing below goes into a Fabric build yet. The facade is written and
 * compiled against Fabric's real class path all the same (`test/platform.test.ts`), so its members are held to what
 * Fabric can do as well as Forge and NeoForge, and the common layer can move Fabric onto it without changing them.
 */
function platform(input: PlatformInput) {
  const v = input.version
  const common = `package ${input.packageName}.${PLATFORM_PACKAGE};

import java.util.List;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Supplier;
import net.fabricmc.fabric.api.biome.v1.BiomeModifications;
import net.fabricmc.fabric.api.biome.v1.BiomeSelectionContext;
import net.fabricmc.fabric.api.biome.v1.BiomeSelectors;
import com.mojang.brigadier.CommandDispatcher;
import net.fabricmc.fabric.api.command.v2.CommandRegistrationCallback;
import net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.fabricmc.fabric.api.event.player.AttackEntityCallback;
import net.fabricmc.fabric.api.event.player.UseBlockCallback;
import net.fabricmc.fabric.api.event.player.UseEntityCallback;
import net.fabricmc.fabric.api.event.player.UseItemCallback;
import net.fabricmc.fabric.api.networking.v1.ServerPlayConnectionEvents;
import net.fabricmc.fabric.api.registry.FuelRegistry;
import net.fabricmc.fabric.api.itemgroup.v1.ItemGroupEvents;
import net.fabricmc.fabric.api.networking.v1.PayloadTypeRegistry;
import net.fabricmc.fabric.api.networking.v1.PlayerLookup;
import net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking;
import net.fabricmc.fabric.api.object.builder.v1.entity.FabricDefaultAttributeRegistry;
import net.minecraft.commands.CommandSourceStack;
import net.minecraft.core.Registry;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.registries.Registries;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.ResourceKey;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.tags.TagKey;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.InteractionResultHolder;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.entity.MobCategory;
import net.minecraft.world.entity.SpawnPlacementTypes;
import net.minecraft.world.entity.SpawnPlacements;
import net.minecraft.world.entity.ai.attributes.AttributeSupplier;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.CreativeModeTab;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.SpawnEggItem;
import net.minecraft.world.level.ItemLike;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.levelgen.Heightmap;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.Vec3;

/** The only way this mod's code reaches the loader (Fabric ${v.minecraft}). Generated by MineMods Studio; the same members on every loader. */
public final class ${PLATFORM_CLASS} {
    public static final String MOD_ID = "${input.modId}";

    private ${PLATFORM_CLASS}() {}

    public static ResourceLocation id(String path) { return ${v.resourceLocation("MOD_ID", "path")}; }

    // Fabric registers at once: the supplier hands back what is already in the registry.
    public static <T extends Block> Supplier<T> block(String name, Supplier<T> factory) {
        T value = Registry.register(BuiltInRegistries.BLOCK, id(name), factory.get());
        return () -> value;
    }

    public static <T extends Item> Supplier<T> item(String name, Supplier<T> factory) {
        T value = Registry.register(BuiltInRegistries.ITEM, id(name), factory.get());
        return () -> value;
    }

    public static <T extends Entity> Supplier<EntityType<T>> entity(String name, Supplier<EntityType<T>> factory) {
        EntityType<T> value = Registry.register(BuiltInRegistries.ENTITY_TYPE, id(name), factory.get());
        return () -> value;
    }

    public static Supplier<SoundEvent> sound(String name) {
        SoundEvent value = Registry.register(BuiltInRegistries.SOUND_EVENT, id(name), SoundEvent.createVariableRangeEvent(id(name)));
        return () -> value;
    }

    /** Anything else of the game's registries (particle types, structure types, mob effects…), by the registry's key. */
    @SuppressWarnings("unchecked")
    public static <R, T extends R> Supplier<T> register(ResourceKey<? extends Registry<R>> registry, String name, Supplier<T> factory) {
        T value = Registry.register((Registry<R>) BuiltInRegistries.REGISTRY.get(registry.location()), id(name), factory.get());
        return () -> value;
    }

    /** How long an item burns in a furnace, in ticks. */
    public static void fuel(Supplier<? extends ItemLike> item, int ticks) { FuelRegistry.INSTANCE.add(item.get(), ticks); }

    /** What a player's use of a block does before the game's own: PASS lets the game go on, anything else is the result. */
    public interface UseBlock { InteractionResult use(Player player, Level level, InteractionHand hand, BlockHitResult hit); }

    public static void onUseBlock(UseBlock handler) { UseBlockCallback.EVENT.register(handler::use); }

    public static <T extends LivingEntity> void attributes(Supplier<EntityType<T>> type, Supplier<AttributeSupplier.Builder> attributes) {
        FabricDefaultAttributeRegistry.register(type.get(), attributes.get());
    }

    public static <T extends Mob> Supplier<Item> spawnEgg(String name, Supplier<EntityType<T>> type, int shell, int spots) {
        return item(name, () -> new SpawnEggItem(type.get(), shell, spots, new Item.Properties()));
    }

    public static <T extends Mob> void spawnRule(Supplier<EntityType<T>> type, SpawnPlacements.SpawnPredicate<T> rule) {
        SpawnPlacements.register(type.get(), SpawnPlacementTypes.ON_GROUND, Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, rule);
    }

    /** Fabric only: a natural spawn is code here (Forge and NeoForge read it from biome modifier files). Biomes by id, groups by the game's biome tags (\`is_forest\`). */
    public static void naturalSpawn(Supplier<? extends EntityType<?>> type, MobCategory category, int weight, int min, int max, List<String> biomes, List<String> tags) {
        java.util.function.Predicate<BiomeSelectionContext> where = context -> false;
        if (!biomes.isEmpty())
            where = where.or(BiomeSelectors.includeByKey(biomes.stream().map(biome -> ResourceKey.create(Registries.BIOME, ResourceLocation.parse(biome))).toList()));
        for (String tag : tags) where = where.or(BiomeSelectors.tag(TagKey.create(Registries.BIOME, ${v.resourceLocation('"minecraft"', "tag")})));
        BiomeModifications.addSpawn(where, category, type.get(), weight, min, max);
    }

    public static void addToTab(ResourceKey<CreativeModeTab> tab, Supplier<? extends ItemLike> item) {
        ItemGroupEvents.modifyEntriesEvent(tab).register(entries -> entries.accept(item.get()));
    }

    /** One server-to-client packet: the generated class travels inside a payload of its own type. */
    public static final class Channel<P> {
        private final CustomPacketPayload.Type<Packet<P>> type;
        private final StreamCodec<FriendlyByteBuf, Packet<P>> codec;

        private Channel(String name, BiConsumer<P, FriendlyByteBuf> write, Function<FriendlyByteBuf, P> read) {
            type = new CustomPacketPayload.Type<>(id(name));
            codec = StreamCodec.of((buffer, packet) -> write.accept(packet.value(), buffer), buffer -> new Packet<>(this, read.apply(buffer)));
        }

        public void sendTo(ServerPlayer player, P value) {
            if (ServerPlayNetworking.canSend(player, type)) ServerPlayNetworking.send(player, new Packet<>(this, value));
        }

        public void sendTracking(Entity entity, P value) { PlayerLookup.tracking(entity).forEach(player -> sendTo(player, value)); }

        public void sendNear(ServerLevel level, double x, double y, double z, double radius, P value) {
            PlayerLookup.around(level, new Vec3(x, y, z), radius).forEach(player -> sendTo(player, value));
        }

        CustomPacketPayload.Type<Packet<P>> type() { return type; }

        Packet<P> packet(P value) { return new Packet<>(this, value); }
    }

    /** A client-to-server packet: \`handler\` runs on the server's main thread with the player who sent it. The client sends with StudioClientPlatform.sendToServer. */
    public static <P> Channel<P> c2s(String name, Class<P> type, BiConsumer<P, FriendlyByteBuf> write, Function<FriendlyByteBuf, P> read, BiConsumer<ServerPlayer, P> handler) {
        Channel<P> made = new Channel<>(name, write, read);
        PayloadTypeRegistry.playC2S().register(made.type, made.codec);
        ServerPlayNetworking.registerGlobalReceiver(made.type, (packet, context) -> context.server().execute(() -> handler.accept(context.player(), packet.value())));
        return made;
    }

    /** The payload a channel's packet travels in. */
    public record Packet<P>(Channel<P> channel, P value) implements CustomPacketPayload {
        @Override public Type<? extends CustomPacketPayload> type() { return channel.type; }
    }

    public static <P> Channel<P> s2c(String name, Class<P> type, BiConsumer<P, FriendlyByteBuf> write, Function<FriendlyByteBuf, P> read) {
        Channel<P> made = new Channel<>(name, write, read);
        PayloadTypeRegistry.playS2C().register(made.type, made.codec);
        return made;
    }

    public static void onServerTick(Consumer<MinecraftServer> tick) { ServerTickEvents.END_SERVER_TICK.register(tick::accept); }

    /** Once a server has loaded its worlds and is about to run its first tick. */
    public static void onServerStarted(Consumer<MinecraftServer> started) { ServerLifecycleEvents.SERVER_STARTED.register(started::accept); }

    /** A player has joined the server (on the server). */
    public static void onPlayerJoin(Consumer<ServerPlayer> join) { ServerPlayConnectionEvents.JOIN.register((handler, sender, server) -> join.accept(handler.player)); }

    /** A living entity has died on the server, with what killed it. */
    public static void onEntityDeath(BiConsumer<LivingEntity, DamageSource> death) { ServerLivingEntityEvents.AFTER_DEATH.register(death::accept); }

    /** What a player's use of the item in a hand does before the game's own: PASS lets the game go on, anything else is the result. */
    public interface UseItem { InteractionResult use(Player player, Level level, InteractionHand hand); }

    public static void onUseItem(UseItem handler) {
        UseItemCallback.EVENT.register((player, level, hand) -> new InteractionResultHolder<>(handler.use(player, level, hand), player.getItemInHand(hand)));
    }

    /** What a player's use of an entity (a right-click on it) does before the game's own: PASS lets the game go on, anything else is the result. */
    public interface UseEntity { InteractionResult use(Player player, Level level, InteractionHand hand, Entity entity); }

    public static void onUseEntity(UseEntity handler) { UseEntityCallback.EVENT.register((player, level, hand, entity, hit) -> handler.use(player, level, hand, entity)); }

    /** The server's commands, to add to: called whenever the server builds them. */
    public static void onCommands(Consumer<CommandDispatcher<CommandSourceStack>> commands) { CommandRegistrationCallback.EVENT.register((dispatcher, context, selection) -> commands.accept(dispatcher)); }

    /** Whether a player's melee attack on an entity goes ahead (asked on both sides, before the game's own attack): false calls it off. */
    public interface Attack { boolean allow(Player player, Entity target); }

    public static void onAttack(Attack handler) { AttackEntityCallback.EVENT.register((player, level, hand, entity, hit) -> handler.allow(player, entity) ? InteractionResult.PASS : InteractionResult.FAIL); }
    /** Whether the world lets this mob change blocks (Boss 能力 15): the game rule mobGriefing; Fabric has no event of its own for it. */
    public static boolean mobGriefing(Entity entity) { return entity.level() instanceof net.minecraft.server.level.ServerLevel level && level.getGameRules().getBoolean(net.minecraft.world.level.GameRules.RULE_MOBGRIEFING); }
}
`
  const client = `package ${input.packageName}.${PLATFORM_PACKAGE};

import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Supplier;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.fabricmc.fabric.api.client.keybinding.v1.KeyBindingHelper;
import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;
import net.fabricmc.fabric.api.client.rendering.v1.EntityRendererRegistry;
import net.fabricmc.fabric.api.client.rendering.v1.HudRenderCallback;
import net.fabricmc.fabric.api.resource.ResourceManagerHelper;
import net.fabricmc.fabric.api.resource.SimpleSynchronousResourceReloadListener;
import net.minecraft.client.KeyMapping;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.packs.PackType;
import net.minecraft.server.packs.resources.ResourceManager;
import net.minecraft.world.BossEvent;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;

/** What only a player's game does (Fabric ${v.minecraft}): its client entry point calls StudioClient.register(), which comes here. */
public final class ${CLIENT_PLATFORM_CLASS} {
    private static final List<BossBar> BOSS_BARS = new ArrayList<>();
    private static final List<CameraRoll> CAMERA_ROLLS = new ArrayList<>();
    private static final List<Fov> FOVS = new ArrayList<>();
    private static int reloads;

    private ${CLIENT_PLATFORM_CLASS}() {}

    public static <T extends Entity> void renderer(Supplier<EntityType<T>> type, EntityRendererProvider<T> provider) {
        EntityRendererRegistry.register(type.get(), provider);
    }

    public static <P> void onS2C(${PLATFORM_CLASS}.Channel<P> channel, Consumer<P> handler) {
        ClientPlayNetworking.registerGlobalReceiver(channel.type(), (packet, context) -> context.client().execute(() -> handler.accept(packet.value())));
    }

    public static <P> void sendToServer(${PLATFORM_CLASS}.Channel<P> channel, P value) { ClientPlayNetworking.send(channel.packet(value)); }

    /** A key the player can rebind under Controls. */
    public static void keyMapping(KeyMapping mapping) { KeyBindingHelper.registerKeyBinding(mapping); }

    public static void onClientTick(Runnable tick) { ClientTickEvents.END_CLIENT_TICK.register(client -> tick.run()); }

    public interface Hud { void draw(GuiGraphics graphics, float partialTick); }

    public static void onHud(Hud hud) { HudRenderCallback.EVENT.register((graphics, counter) -> hud.draw(graphics, counter.getGameTimeDeltaPartialTick(true))); }
    /** A particle type's look in a player's game (A 组: the mod's own particles): \`provider\` makes its particles from the pictures the game loaded for the type. */
    public static <T extends net.minecraft.core.particles.ParticleOptions> void particle(Supplier<? extends net.minecraft.core.particles.ParticleType<T>> type, java.util.function.Function<net.minecraft.client.particle.SpriteSet, net.minecraft.client.particle.ParticleProvider<T>> provider) {
        net.fabricmc.fabric.api.client.particle.v1.ParticleFactoryRegistry.getInstance().register(type.get(), sprites -> provider.apply(sprites));
    }

    public interface BossBar { int draw(GuiGraphics graphics, BossEvent bar, int top); }

    /** Fabric has no event for a boss bar: a mixin into the game's boss bar overlay (fabric/boss-bar.ts, \`bossBarOverlayMixin\`) asks Hooks.bossBar for each bar it draws. */
    public static void onBossBar(BossBar bar) { BOSS_BARS.add(bar); }

    public interface CameraRoll { float roll(float partialTick); }

    /** Degrees the view is turned about the line of sight this frame (Boss 能力 8). Fabric has no event: a mixin into the camera asks Hooks.cameraRoll and turns the camera's rotation. */
    public static void onCameraRoll(CameraRoll roll) { CAMERA_ROLLS.add(roll); }

    public interface Fov { double fov(double fov, float partialTick); }

    /** The field of view of the world (not the hand's) this frame, from the one the game would use (Boss 能力 8). Fabric has no event: a mixin into GameRenderer.getFov asks Hooks.fov. */
    public static void onFov(Fov fov) { FOVS.add(fov); }

    public static void onReload(Runnable reload) {
        ResourceLocation id = ${PLATFORM_CLASS}.id("reload_" + reloads++);
        ResourceManagerHelper.get(PackType.CLIENT_RESOURCES).registerReloadListener(new SimpleSynchronousResourceReloadListener() {
            @Override public ResourceLocation getFabricId() { return id; }

            @Override public void onResourceManagerReload(ResourceManager manager) { reload.run(); }
        });
    }

    /** What Fabric's mixins call, where Forge and NeoForge have an event; not for the common layer. */
    public static final class Hooks {
        private Hooks() {}

        /** The pixels the first handler that draws this bar took, or 0: the game draws it. */
        public static int bossBar(GuiGraphics graphics, BossEvent bar, int top) {
            for (BossBar handler : BOSS_BARS) {
                int taken = handler.draw(graphics, bar, top);
                if (taken > 0) return taken;
            }
            return 0;
        }

        /** The degrees every handler turns the view by this frame, added. */
        public static float cameraRoll(float partialTick) {
            float roll = 0.0f;
            for (CameraRoll handler : CAMERA_ROLLS) roll += handler.roll(partialTick);
            return roll;
        }

        /** The field of view every handler makes of the game's, one after another. */
        public static double fov(double fov, float partialTick) {
            for (Fov handler : FOVS) fov = handler.fov(fov, partialTick);
            return fov;
        }
    }
}
`
  const paths = platformPaths(input.packageName)
  return { [paths.common]: common, [paths.client]: client }
}

export const FABRIC_LOADER: LoaderAdapter = {
  kind: "fabric",
  facade: false,
  modFile: "src/main/resources/fabric.mod.json",
  spawns: { kind: "code" },
  platformFiles: platform,
  mainClass: () => null,
  spawnFiles: () => ({}),
  addMixins: addMixinClasses,
  // Fabric adds an ore to its biomes in code (`StudioWorldgen`, fabric/worldgen.ts).
  featureFiles: () => ({}),
  // Vanilla's way, which Fabric keeps: what `fabric/block-shape.ts` writes into a block with a shape.
  blockExperience: (range) => ({
    member: `    @Override
    protected void spawnAfterBreak(BlockState state, ServerLevel world, BlockPos pos, ItemStack tool, boolean dropExperience) {
        super.spawnAfterBreak(state, world, pos, tool, dropExperience);
        if (dropExperience) tryDropExperience(world, pos, tool, ${range});
    }`,
    imports: ["net.minecraft.world.level.block.state.BlockState", "net.minecraft.world.item.ItemStack", "net.minecraft.server.level.ServerLevel", "net.minecraft.core.BlockPos"],
  }),
}
